import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch59Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("sm1_en_133","sm12_en_191");
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static ServerMatch aiGame(String id){return GeneratedRuleBatch23Test.fixture(NonPokemonBatch2Test.DATA.trainer(id).orElseThrow(),0,EnergyType.GRASS);}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    public static void main(String[] args){skull();erika();System.out.println("NonPokemonBatch59Test passed: both owners; mandatory two Energy including Special, one/zero available and empty hand, reveal-before-choice, exact physical discard and invalid choices atomic; Erika independent zero-to-three draws in controller-first order with short/empty decks");}
    static void skull(){for(UUID p:List.of(A,B))for(int count=0;count<=3;count++)for(boolean empty:List.of(false,true)){
        var m=aiGame(IDS.get(0));UUID other=p.equals(A)?B:A;if(p.equals(B))m.endTurn(A);var energies=new ArrayList<CardInstance>();if(count>0)energies.add(hand(m,other,"special"));if(count>1)energies.add(hand(m,other,"energy"));if(count>2)energies.add(hand(m,other,"wrong"));var nonenergy=hand(m,other,"basic");var keep=new HashSet<>(energies);if(!empty)keep.add(nonenergy);var discard=m.privateView(other).hand().stream().filter(c->!keep.contains(c)).map(CardInstance::instanceId).toList();m.discardHandCardsByEffect(p,other,discard);
        var source=hand(m,p,"trainer");check(m.canPlayTrainer(p,source.instanceId(),null)==(!empty||count>0),"Team Skull empty-hand eligibility");if(empty&&count==0)continue;var before=m.privateView(other).hand();m.playTrainer(p,source.instanceId(),null);check(m.privateView(other).hand().equals(before),"Discard occurred before reveal");NonPokemonBatch14Test.reveal(m);
        if(count==0){NonPokemonBatch2Test.settle(m);check(m.privateView(other).hand().equals(before),"No-Energy hand lost a card");continue;}
        var q=m.effectCardPrompt(p);int required=Math.min(2,count);check(q.minimum()==required&&q.maximum()==required&&new HashSet<>(q.candidates()).equals(new HashSet<>(energies)),"Wrong Energy filter/mandatory count");var chosen=energies.subList(0,required).stream().map(CardInstance::instanceId).toList();GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(other,q.resolutionId(),q.step(),chosen));GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(p,q.resolutionId(),q.step(),List.of()));if(count>=2)GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(p,q.resolutionId(),q.step(),chosen.subList(0,1)));if(count==3)GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(p,q.resolutionId(),q.step(),energies.stream().map(CardInstance::instanceId).toList()));if(!empty)GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(nonenergy.instanceId())));check(m.privateView(other).hand().equals(before),"Invalid discard partially mutated hand");m.submitEffectCards(p,q.resolutionId(),q.step(),chosen);NonPokemonBatch2Test.settle(m);check(m.privateView(other).hand().size()==before.size()-required&&m.privateView(other).discard().stream().map(CardInstance::instanceId).toList().containsAll(chosen),"Failed exact selected Energy discard");
    }}
    static void erika(){for(UUID p:List.of(A,B))for(int ownDeck:List.of(0,1,4))for(int otherDeck:List.of(0,2,4))for(int ownDraw=0;ownDraw<=3;ownDraw++)for(int otherDraw=0;otherDraw<=3;otherDraw++){
        var m=aiGame(IDS.get(1));UUID other=p.equals(A)?B:A;if(p.equals(B))m.endTurn(A);m.drawCardsByEffect(p,p,m.privateView(p).deck().size()-ownDeck);m.drawCardsByEffect(p,other,m.privateView(other).deck().size()-otherDeck);var source=hand(m,p,"trainer");int own=m.privateView(p).hand().size(),opp=m.privateView(other).hand().size();check(m.canPlayTrainer(p,source.instanceId(),null)==(ownDeck+otherDeck>0),"Erika empty decks eligibility");if(ownDeck+otherDeck==0)continue;m.playTrainer(p,source.instanceId(),null);
        if(ownDeck>0){choose(m,p,other,ownDraw);check(m.privateView(p).hand().size()==own-1+Math.min(ownDraw,ownDeck)&&m.privateView(other).hand().size()==opp,"Erika did not draw own cards first");}
        if(otherDeck>0)choose(m,other,p,otherDraw);NonPokemonBatch2Test.settle(m);check(m.privateView(p).hand().size()==own-1+Math.min(ownDraw,ownDeck)&&m.privateView(other).hand().size()==opp+Math.min(otherDraw,otherDeck),"Erika draws were not independent/clamped");check(m.privateView(p).discard().contains(source),"Erika source disposition wrong");
    }}
    static void choose(ServerMatch m,UUID player,UUID denied,int amount){var q=m.effectChoicePrompt(player);check(q.optionsZh().size()==4,"Missing independent zero-to-three draw choices");int index=amount==0?3:amount-1;GeneratedRuleBatch8Test.reject(()->m.effectChoicePrompt(denied));GeneratedRuleBatch8Test.reject(()->m.chooseEffectOption(denied,q.resolutionId(),q.step(),index));m.chooseEffectOption(player,q.resolutionId(),q.step(),index);}
}
